latest_checkpoint() {
  local run_dir="$1"
  python - "$run_dir" <<'__PY_LATEST__'
from pathlib import Path
import sys
import torch

run_dir = Path(sys.argv[1])
candidates = []
for name in ("checkpoint.pt", "checkpoint_recovery.pt"):
    path = run_dir / name
    if path.is_file():
        candidates.append(path)
candidates.extend(run_dir.glob("checkpoint_epoch_*.pt"))

valid = []
for path in candidates:
    try:
        try:
            checkpoint = torch.load(
                path, map_location="cpu", weights_only=False
            )
        except TypeError:
            checkpoint = torch.load(path, map_location="cpu")
        valid.append(
            (
                int(checkpoint.get("global_step", -1)),
                int(checkpoint.get("epoch", -1)),
                path.stat().st_mtime_ns,
                path,
            )
        )
    except Exception:
        pass

if valid:
    print(max(valid, key=lambda item: item[:3])[3])
__PY_LATEST__
}

checkpoint_epoch() {
  python - "$1" <<'__PY_CHECKPOINT__'
import sys, torch
p=sys.argv[1]
try:
    ck=torch.load(p,map_location='cpu',weights_only=False)
except TypeError:
    ck=torch.load(p,map_location='cpu')
print(int(ck.get('epoch',-1)))
__PY_CHECKPOINT__
}

run_logged() {
  local label="$1"; shift
  local log="$LOG_DIR/${label}.log"
  echo
  echo "============================================================"
  echo "START $label at $(date)"
  echo "LOG   $log"
  echo "============================================================"
  "$@" 2>&1 | tee "$log"
  local code=${PIPESTATUS[0]}
  if [[ $code -ne 0 ]]; then
    echo "ERROR: $label failed with code $code"
    return "$code"
  fi
  return 0
}

train_one() {
  local label="$1"
  local out_dir="$2"
  shift 2
  local extra=("$@")
  local final="$out_dir/checkpoint_epoch_$(printf '%03d' "$EPOCHS").pt"

  if [[ -f "$final" ]] && [[ "$(checkpoint_epoch "$final")" -ge "$EPOCHS" ]]; then
    echo "SKIP TRAIN $label: $final already complete"
    return 0
  fi

  local resume=()
  local latest=""
  latest="$(latest_checkpoint "$out_dir" || true)"
  if [[ -n "$latest" && -f "$latest" ]]; then
    resume=(--resume "$latest")
    echo "$label resumes from $latest"
  fi

  run_logged "train_${label}" \
    env LD_LIBRARY_PATH="" python -m "$TRAIN_MODULE" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split train \
      --model-size default \
      --epochs "$EPOCHS" \
      --batch-size 16 \
      --num-workers 4 \
      --rollout-window 20 \
      --rollout-horizon 5 \
      --window-mode random \
      --samples-per-epoch 50000 \
      --enemy-visibility-mask \
      --enemy-sight-range 9.0 \
      --temporal-loss lambda \
      --td-lambda 0.9 \
      --r2-dyn-scale 1.0 \
      --r2-rep-scale 0.1 \
      --r2-barlow-scale 0.05 \
      --r2-barlow-lambda 0.0005 \
      --r2-latent-normalize \
      --sigreg-weight 0.01 \
      --r2-sigreg-divide-by-dim \
      --r2-sigreg-knots 17 \
      --r2-sigreg-num-proj 1024 \
      --r2-sigreg-proj-chunk 64 \
      --r2-sigreg-max-samples 0 \
      --decoder-weight 0.01 \
      --presence-weight 0.01 \
      --rollout-memory-dim 128 \
      --target-mode full \
      --action-conditioned-memory \
      --one-step-weight 0.5 \
      --lr-warmup-steps 2000 \
      --aux-loss-warmup-steps 2000 \
      --grad-clip 1.0 \
      --amp-dtype auto \
      --amp-init-scale 1024 \
      --amp-growth-interval 10000 \
      --amp-fallback-after-nonfinite 3 \
      --nonfinite-lr-backoff 0.5 \
      --min-learning-rate 0.000001 \
      --adam-eps 0.000001 \
      --checkpoint-every-steps 250 \
      --max-consecutive-nonfinite-grad-steps 0 \
      --max-total-nonfinite-grad-steps 0 \
      --device cuda \
      --amp \
      "${extra[@]}" \
      "${resume[@]}" \
      --out-dir "$out_dir" \
      --wandb \
      --wandb-project SMAC-JEPA-losses \
      --wandb-name "$label"

  if [[ ! -f "$final" ]]; then
    echo "ERROR: expected final checkpoint missing: $final"
    return 1
  fi
  return 0
}

eval_one() {
  local label="$1"
  local checkpoint="$2"
  local out_dir="$EVAL_ROOT/$label"
  local summary="$out_dir/eval_seqmem_combined_summary.csv"
  if [[ -f "$summary" && "$FORCE_EVAL" != "1" ]]; then
    echo "SKIP EVAL $label: $summary exists"
    return 0
  fi
  mkdir -p "$out_dir"
  run_logged "eval_${label}" \
    env LD_LIBRARY_PATH="" python "$EVALUATOR" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split eval \
      --checkpoint "$checkpoint" \
      --out-dir "$out_dir" \
      --probe-dir "$PROBE_DIR" \
      --batch-size 16 \
      --num-workers 4 \
      --max-batches "$EVAL_MAX_BATCHES" \
      --diagnostics \
      --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES" \
      --eval-rollout-horizon 5 \
      --target-mode full \
      --window-mode sequential \
      --thresholds 0.01 0.05 0.1 \
      --probe-decoder \
      --probe-train-split train \
      --probe-epochs "$PROBE_EPOCHS" \
      --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES" \
      --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH" \
      --probe-lr 0.001 \
      --probe-weight-decay 0.00001 \
      --probe-seed 123 \
      --device cuda \
      --amp
}

EXP16_DIR="runs/rnn_seqmem_exp16_blocker_fixed_full_h5"
EXP17_DIR="runs/rnn_seqmem_exp17_blocker_fixed_ema_full_h5"
EXP18_DIR="runs/rnn_seqmem_exp18_blocker_fixed_ema_memory_barlow_full_h5"
EXP19_DIR="runs/rnn_seqmem_exp19_blocker_fixed_ema_memory_barlow_event_balanced_full_h5"

declare -a SUCCESSFUL_CHECKPOINTS=()
declare -a FAILED_STAGES=()

run_train_then_eval() {
  local eval_label="$1"
  local train_label="$2"
  local run_dir="$3"
  shift 3

  if train_one "$train_label" "$run_dir" "$@"; then
    if [[ -f "$run_dir/checkpoint.pt" ]]; then
      if eval_one "$eval_label" "$run_dir/checkpoint.pt"; then
        SUCCESSFUL_CHECKPOINTS+=("$run_dir/checkpoint.pt")
      else
        FAILED_STAGES+=("${eval_label}:evaluation")
      fi
    else
      echo "NO COMPLETED CHECKPOINT FOR $eval_label; skipping evaluation"
      FAILED_STAGES+=("${eval_label}:missing_checkpoint")
    fi
  else
    echo "TRAINING FAILED FOR $eval_label; continuing to next experiment"
    FAILED_STAGES+=("${eval_label}:training")
  fi
}

run_train_then_eval \
  exp16 \
  "rnn-seqmem-exp16-blocker-fixed-full-h5" \
  "$EXP16_DIR" \
  --no-ema-target-encoder \
  --memory-barlow-scale 0.0 \
  --no-event-balanced-sampling

run_train_then_eval \
  exp17 \
  "rnn-seqmem-exp17-blocker-fixed-ema-full-h5" \
  "$EXP17_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.0 \
  --no-event-balanced-sampling

run_train_then_eval \
  exp18 \
  "rnn-seqmem-exp18-blocker-fixed-ema-memory-barlow-full-h5" \
  "$EXP18_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.01 \
  --no-event-balanced-sampling

run_train_then_eval \
  exp19 \
  "rnn-seqmem-exp19-blocker-fixed-ema-memory-barlow-event-balanced-full-h5" \
  "$EXP19_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.01 \
  --event-balanced-sampling \
  --event-fraction 0.30 \
  --event-pool-fraction 0.20 \
  --event-movement-threshold 0.01 \
  --event-state-threshold 0.001 \
  --event-attack-action-min 6 \
  --event-min-transitions 1

COMBINED_OUT="$EVAL_ROOT/combined"
mkdir -p "$COMBINED_OUT"

if [[ ${#SUCCESSFUL_CHECKPOINTS[@]} -gt 0 ]]; then
  combined_checkpoint_args=()
  for checkpoint in "${SUCCESSFUL_CHECKPOINTS[@]}"; do
    combined_checkpoint_args+=(--checkpoint "$checkpoint")
  done

  if ! run_logged "eval_combined_successful_experiments" \
    env LD_LIBRARY_PATH="" python "$EVALUATOR" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split eval \
      "${combined_checkpoint_args[@]}" \
      --out-dir "$COMBINED_OUT" \
      --probe-dir "$PROBE_DIR" \
      --batch-size 16 \
      --num-workers 4 \
      --max-batches "$EVAL_MAX_BATCHES" \
      --diagnostics \
      --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES" \
      --eval-rollout-horizon 5 \
      --target-mode full \
      --window-mode sequential \
      --thresholds 0.01 0.05 0.1 \
      --probe-decoder \
      --probe-train-split train \
      --probe-epochs "$PROBE_EPOCHS" \
      --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES" \
      --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH" \
      --probe-lr 0.001 \
      --probe-weight-decay 0.00001 \
      --probe-seed 123 \
      --device cuda \
      --amp
  then
    FAILED_STAGES+=("combined:evaluation")
  fi
else
  echo "No experiment completed successfully; combined evaluation skipped."
  FAILED_STAGES+=("combined:no_successful_checkpoints")
fi

echo
echo "============================================================"
echo "SUITE FINISHED"
echo "Successful checkpoints: ${#SUCCESSFUL_CHECKPOINTS[@]}"
if [[ -f "$COMBINED_OUT/eval_seqmem_combined_summary.csv" ]]; then
  echo "Combined summary: $COMBINED_OUT/eval_seqmem_combined_summary.csv"
fi
echo "Commands: $LOG_DIR/commands.txt"
echo "Logs:     $LOG_DIR"
if [[ ${#FAILED_STAGES[@]} -gt 0 ]]; then
  echo "Failed/skipped stages:"
  printf '  %s\n' "${FAILED_STAGES[@]}"
fi
echo "============================================================"

# All experiments have now been attempted. Return a non-zero status only after
# the suite has finished, rather than terminating at the first failed run.
if [[ ${#FAILED_STAGES[@]} -gt 0 ]]; then
  exit 1
fi
